/**
 * Site search (replaces the WordPress search, which answered <home>?s=<terms>).
 * Loaded only when the URL contains ?s=. It reads the search index generated by the build
 * (/assets/search/<lang>.json: title, url and text of every page) and replaces the page
 * content with a results list that uses the markup and classes of the Astra search template.
 * Like WordPress, every word must appear in the title or the text; pages whose title
 * matches come first, then the most recently published.
 * Differences with WordPress (documented in docs/dynamic-features.md): no author line,
 * no pagination (the site has 10 pages per language).
 */
(function () {
  'use strict';
  var cfgEl = document.getElementById('site-search-config');
  if (!cfgEl) return;
  var cfg = JSON.parse(cfgEl.textContent);
  var query = (new URLSearchParams(location.search).get('s') || '').trim();
  var norm = function (s) { return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); };
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };

  function formHtml() {
    var tpl = document.getElementById('search-form-template');
    return tpl ? tpl.innerHTML : '';
  }

  function render(results) {
    document.title = cfg.title.replace('{query}', query);
    document.body.className = cfg.bodyClass + (document.body.classList.contains('ast-header-break-point') ? ' ast-header-break-point' : '');
    document.body.setAttribute('itemtype', 'https://schema.org/SearchResultsPage');
    // like the WordPress search template: opaque header, which has no logo on this site
    document.querySelectorAll('.site-logo-img').forEach(function (el) { el.innerHTML = ''; });
    if (!document.querySelector('link[href="' + cfg.css + '"]')) {
      var link = document.createElement('link'); link.rel = 'stylesheet'; link.href = cfg.css; document.head.appendChild(link);
    }
    var items = results.map(function (r) {
      return '<article class="post-' + r.id + ' page type-page status-publish hentry ast-grid-common-col ast-full-width ast-article-post ast-width-md-12 ast-archive-post" id="post-' + r.id + '" itemtype="https://schema.org/CreativeWork" itemscope="itemscope">' +
        '<div class="ast-post-format- ast-no-thumb blog-layout-1 ast-article-inner ast-no-date-box"><div class="post-content ast-grid-common-col">' +
        '<div class="ast-blog-featured-section post-thumb ast-blog-single-element"></div>' +
        '<h2 class="entry-title ast-blog-single-element" itemprop="headline"><a href="' + esc(r.url) + '" rel="bookmark">' + esc(r.title) + '</a></h2>' +
        '<div class="ast-excerpt-container ast-blog-single-element"></div>' +
        '<p class="ast-blog-single-element ast-read-more-container read-more"> <a class="" href="' + esc(r.url) + '"> <span class="screen-reader-text">' + esc(r.title) + '</span> ' + esc(cfg.readMore) + '</a></p>' +
        '</div></div></article>';
    }).join('');
    var body = results.length
      ? '<div class="ast-row">' + items + '</div>'
      : '<section class="no-results not-found"><div class="page-content"><p>' + esc(cfg.noResults) + '</p>' + formHtml() + '</div></section>';
    var container = document.querySelector('#content > .ast-container');
    container.innerHTML = '<div id="primary" class="content-area primary ast-grid-1 ast-grid-md-1 ast-grid-sm-1">' +
      '<section class="ast-archive-description"><h1 class="page-title ast-archive-title">' + esc(cfg.heading) + ' <span>' + esc(query) + '</span></h1></section>' +
      '<main id="main" class="site-main">' + body + '</main></div>';
    var field = container.querySelector('.search-field');
    if (field) field.value = query;
  }

  fetch(cfg.index).then(function (r) { return r.json(); }).then(function (index) {
    var words = norm(query).split(/\s+/).filter(Boolean);
    var hits = index.map(function (p) {
      var title = norm(p.title), text = norm(p.text);
      var all = words.every(function (w) { return title.indexOf(w) >= 0 || text.indexOf(w) >= 0; });
      return all ? { p: p, inTitle: words.some(function (w) { return title.indexOf(w) >= 0; }) } : null;
    }).filter(Boolean);
    hits.sort(function (a, b) { return (b.inTitle - a.inTitle) || (b.p.published > a.p.published ? 1 : b.p.published < a.p.published ? -1 : 0); });
    render(words.length ? hits.map(function (h) { return h.p; }) : index);
  }).catch(function () { render([]); });
})();
